entries[356390] = { ["name"] = "Pallid Command", ["text"] = "Runecarving Power\n[ Discipline : Casting Unholy Nova summons a Brooding Cleric that gains 2% additional damage and healing each time an enemy affected by Unholy Transfusion is damaged by an ally, up to 100%.\n\nThe Brooding Cleric serves you for 20 sec, healing an ally for (40% of Spell Power). ] [ Shadow : Casting Unholy Nova summons a Rattling Mage that gains 2% additional damage and healing each time an enemy affected by Unholy Transfusion is damaged by an ally, up to 100%.\n\nThe Rattling Mage serves you for 20 sec, blasting your target for (25.1% of Spell Power) Shadow damage. /\n\nHoly\nCasting Unholy Nova summons a Brooding Cleric that gains 2% additional damage and healing each time an enemy affected by Unholy Transfusion is damaged by an ally, up to 100%.\n\nThe Brooding Cleric serves you for 20 sec, healing an ally for (40% of Spell Power). ] Runecarve on: Feet, Finger\nSource: Granted at Renown 48 with your covenant.\nRequires: Priest" }
entries[356391] = { ["name"] = "Bwonsamdi's Pact", ["text"] = "Runecarving Power\nInstant\nEnter a pact with the Death Loa, calling forth a haunted mask that lingers on a target until Fae Guardians ends.\n\nHaunted Mask: Copies the benefit of the current faerie on its target. Follows your Direct Mask.\nRunecarve on: Head, Waist, Hands\nSource: Granted at Renown 48 with your covenant.\nRequires: Priest" }
entries[356392] = { ["name"] = "Shadow Word: Manipulation", ["text"] = "Runecarving Power\nInstant\nMindgames lasts an additional 3 sec and reverses an additional 10% damage or healing. When Mindgames can no longer reverse healing or damage, gain 5% Critical Strike for each second remaining for 10 sec.\nRunecarve on: Neck, Wrist\nSource: Granted at Renown 48 with your covenant.\nRequires: Priest" }
